describe('Document Language Declaration in HTML Tag', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should declare document language in html tag and render content correctly', () => {
    // Verify html tag exists
    cy.get('html').should('be.visible');

    // Verify lang attribute is present and correct
    cy.get('html').should('have.attr', 'lang', 'en');

    // Verify content is rendered with correct language
    cy.get('[data-testid="main-heading"]').should('contain', 'Welcome');
    cy.get('[data-testid="paragraph-text"]').should('contain', 'This is a sample paragraph');

    // Verify accessibility features are available
    cy.get('[data-testid="aria-label"]').should('be.visible');
    cy.get('[data-testid="aria-label"]').should('have.attr', 'aria-label');

    // Verify language is respected by browser
    cy.get('body').should('have.attr', 'lang', 'en');
  });

  it('should handle missing lang attribute and display fallback', () => {
    // Intercept the page load with missing lang attribute
    cy.intercept('GET', '/').as('pageLoad');
    cy.visit('/');

    // Verify html tag exists
    cy.get('html').should('be.visible');

    // Verify lang attribute is missing or empty
    cy.get('html').should('not.have.attr', 'lang');

    // Verify fallback language is used
    cy.get('body').should('have.attr', 'lang', 'und');

    // Verify content is still rendered
    cy.get('[data-testid="main-heading"]').should('contain', 'Welcome');
    cy.get('[data-testid="paragraph-text"]').should('contain', 'This is a sample paragraph');

    // Verify accessibility features are still available
    cy.get('[data-testid="aria-label"]').should('be.visible');
    cy.get('[data-testid="aria-label"]').should('have.attr', 'aria-label');
  });
});
